-- VIAVI MicroNIR near infrared spectrometers (1700 EC, OnSite-W, PAT-U, PAT-W) from the VIAVI data sheets.
-- Run once in Supabase -> SQL Editor (choose "Run without RLS" if asked). Safe to run again.
alter table products add column if not exists features jsonb not null default '[]'::jsonb;
insert into brands (name, slug, website_url) values ('VIAVI Solutions', 'viavi-solutions', 'https://www.viavisolutions.com/')
on conflict (slug) do update set name = excluded.name, website_url = excluded.website_url;
insert into categories (name, slug, sort_order) values ('Spectrophotometer', 'spectrophotometer', 7) on conflict (slug) do nothing;

insert into products (sku, name, slug, description, specs, features, category_id, brand_id, image_url, is_active)
select v.sku, v.name, v.slug, v.description, v.specs::jsonb, v.features::jsonb, c.id, b.id, v.image_url, true
from (values
  ('VIAVI-MICRONIR-1700EC', 'VIAVI MicroNIR 1700 EC Ultra-Compact NIR Spectrometer', 'viavi-micronir-1700-ec-nir-spectrometer', 'The MicroNIR 1700 EC is a lightweight, cost-effective near infrared (NIR) spectrometer, under 47 mm wide and only 116 g, with light source, optics, electronics and detector in one USB-C powered package. It works in diffuse reflection, transmission or transflection, and is designed for exploratory data analysis and calibration model development.', '[["Model", "MicroNIR 1700 EC"], ["Illumination source", "Two integrated vacuum tungsten lamps, >40,000 h lifetime"], ["Dispersing element", "VIAVI linear variable filter (LVF)"], ["Detector", "128-pixel InGaAs photodiode array"], ["Wavelength range", "908 – 1676 nm (11,012 – 5966 cm⁻¹)"], ["Pixel-to-pixel interval", "6.2 nm"], ["Spectral resolution (FWHM)", "<1.25% of centre wavelength (e.g. <12.5 nm at 1000 nm)"], ["A/D converter", "16 bit"], ["Integration time", "10 ms typical"], ["Working distance", "0 – 15 mm (best in contact with the window)"], ["Computer interface", "USB-C"], ["Power", "USB-C powered (<500 mA at 5 V)"], ["Weight", "116 g (4 oz)"], ["Size", "47 mm diameter × 60 mm height"], ["Software included", "MicroNIR Pro (Windows 7 and above)"], ["Operating temperature", "−20 to +40 °C (non-condensing)"], ["Storage temperature", "−40 to +70 °C"], ["Package drop test", "ISTA 2A"], ["Standard accessories", "Measurement collar with sapphire window, Spectralon reference target, USB-C cable, flash drive with software and manuals"], ["Applications", "Pharmaceutical; food, feed and agriculture; industrial processing"]]', '["Covers all important NIR bands with excellent penetration depth", "Compact and robust, no moving parts, no maintenance or calibration required", "Real-time prediction and method management", "MicroNIR Pro software for data acquisition, method development and real-time prediction (PCA, PLS, Spectral Match Value, Moving Block)", "OEM version available"]', '/products/viavi/micronir-1700-ec.jpg'),
  ('VIAVI-MICRONIR-ONSITE-W', 'VIAVI MicroNIR OnSite-W Handheld Wireless NIR Spectrometer', 'viavi-micronir-onsite-w-handheld-nir-spectrometer', 'The MicroNIR OnSite-W is a rugged, wireless, battery-operated NIR spectrometer for rapid handheld material analysis in the factory or in the field. With an integrated battery, one-click button and Bluetooth, it runs from a tablet or PC with an intuitive interface that needs minimal training.', '[["Model", "MicroNIR OnSite-W"], ["Illumination source", "Two integrated vacuum tungsten lamps, >40,000 h lifetime"], ["Dispersing element", "VIAVI linear variable filter (LVF)"], ["Detector", "128-pixel InGaAs photodiode array"], ["Wavelength range", "908 – 1676 nm (11,012 – 5966 cm⁻¹)"], ["Pixel-to-pixel interval", "6.2 nm"], ["Spectral resolution (FWHM)", "<1.25% of centre wavelength (e.g. <12.5 nm at 1000 nm)"], ["A/D converter", "16 bit"], ["Dynamic range (max)", "1000:1"], ["Measurement time", "0.25 – 0.5 s typical"], ["Signal-to-noise ratio", "25,000 typical"], ["Connectivity", "Bluetooth 4.1 (BLE) and USB 2.0"], ["Battery", "Rechargeable Li-ion, >10 h with lamps on; 3.5 h charge"], ["Weight", "<250 g (<9 oz)"], ["Size", "194 mm length × 47 mm diameter"], ["Export formats", "CAMO .unsb, Grams .spc, ASCII .csv"], ["Software", "MicroNIR Pro 3.0+ and tablet application (Windows 10 Pro)"], ["Dust and water resistance", "IP65 and IP67"], ["Shock and vibration", "MIL-PRF-28800F Class 2"], ["Operating temperature", "−20 to 40 °C (non-condensing)"], ["Standard accessories", "Two measurement collars with sapphire windows, protected white reference, rugged carrying case, USB cable"], ["Applications", "Pharmaceutical raw materials, polymers and chemicals, narcotics and explosives, grain and forage, tobacco, meat and dairy"]]', '["Rapid, non-destructive NIR analysis in real time", "Wireless, compact and rugged for one-hand operation", "One-click data acquisition button", "Battery runs over 10 hours", "IP65 / IP67 rated for wet and dusty environments", "Bluetooth or USB to tablet or PC", "Pharmacopoeia qualification (EP 2.2.40, USP 1119) and 21 CFR Part 11 tools"]', '/products/viavi/micronir-onsite-w.jpg'),
  ('VIAVI-MICRONIR-PAT-U', 'VIAVI MicroNIR PAT-U Process NIR Analyzer', 'viavi-micronir-pat-u-process-nir-analyzer', 'The MicroNIR PAT-U is a rugged, fit-for-purpose NIR process spectrometer for real-time monitoring in pharmaceutical, food and industrial process analytical technology (PAT). It has no moving parts or fibre optic cables, a stainless steel body with sapphire window, and mounts directly on process equipment with a sanitary flange.', '[["Model", "MicroNIR PAT-U"], ["Illumination source", "Two integrated vacuum tungsten lamps, >40,000 h lifetime"], ["Dispersing element", "VIAVI linear variable filter (LVF)"], ["Detector", "128-pixel InGaAs photodiode array"], ["Wavelength range", "908 – 1676 nm (11,012 – 5966 cm⁻¹)"], ["Pixel-to-pixel interval", "6.2 nm"], ["Spectral resolution (FWHM)", "<1.25% of centre wavelength (e.g. <12.5 nm at 1000 nm)"], ["A/D converter", "16 bit"], ["Integration time", "10 ms typical"], ["Working distance", "0 – 15 mm (best in contact with the window)"], ["Computer interface", "USB 2.0"], ["Power", "USB powered (<500 mA at 5 V)"], ["Weight", "311 g"], ["Size", "45 mm diameter × 69 mm length"], ["Enclosure", "Stainless steel with sapphire window, washable, IP65 and IP67"], ["Software included", "MicroNIR Pro (Windows 7, 8 and 10)"], ["Operating temperature", "0 to 40 °C (non-condensing)"], ["Process integration", "Sanitary flange mount with collet assembly and tri-clover clamp; weld-in flange kit available"], ["Standard accessories", "Measurement collar with sapphire window, white reference target, USB cable, rugged carrying case"], ["Applications", "Fluid bed drying, feed frame, granulation, content uniformity; moisture, protein, fat; reaction monitoring, polymers, petrochemicals"]]', '["Non-invasive, real-time NIR analysis", "Washable IP65 / IP67 enclosure", "Smallest process NIR analyzer, easy to integrate", "Excellent instrument-to-instrument repeatability for calibration transfer", "MicroNIR Pro chemometric software"]', '/products/viavi/micronir-pat-u.jpg'),
  ('VIAVI-MICRONIR-PAT-W', 'VIAVI MicroNIR PAT-W Wireless Process NIR Analyzer', 'viavi-micronir-pat-w-wireless-process-nir-analyzer', 'The MicroNIR PAT-W is a wireless NIR process spectrometer for real-time monitoring of blend homogeneity, loss on drying, compaction and content uniformity. Onboard WiFi and a replaceable battery let it be installed on tumble blenders, and its stainless steel and aluminium housing is IP65/IP67 rated for GMP environments.', '[["Model", "MicroNIR PAT-W"], ["Illumination source", "Two integrated vacuum tungsten lamps, >40,000 h lifetime"], ["Dispersing element", "VIAVI linear variable filter (LVF)"], ["Detector", "128-pixel InGaAs photodiode array"], ["Wavelength range", "908 – 1676 nm (11,012 – 5966 cm⁻¹)"], ["Pixel-to-pixel interval", "6.2 nm"], ["Spectral resolution (FWHM)", "<1.25% of centre wavelength (e.g. <12.5 nm at 1000 nm)"], ["A/D converter", "16 bit"], ["Integration time", "10 ms typical"], ["Working distance", "0 – 15 mm (best in contact with the window)"], ["Computer interface", "TCP/IP Cat5 Ethernet; 802.11g WiFi"], ["Power", "Rechargeable Li-ion battery (7.5 V, 6400 mAh, >8 h); external 110 – 240 V AC"], ["Weight", "1210 g (including 239 g battery)"], ["Size", "168 × 139 × 131 mm (L × W × H)"], ["Enclosure", "Stainless steel and aluminium with sapphire window, IP65 and IP67"], ["Software included", "MicroNIR Pro (Windows 7, 8 and 10); optional OPC interface"], ["Operating temperature", "0 to 40 °C (non-condensing)"], ["Standard accessories", "Optical trigger and 24 V power supply, WiFi router, two batteries and charger, 99% reference standard, rugged carrying case"], ["Applications", "Blend and content uniformity, fluid bed drying, granulation; moisture, protein, fat; reaction monitoring, polymers, petrochemicals"]]', '["WiFi or Ethernet for control and data", "Replaceable Li-ion battery, over 8 hours run time", "Multi-axis sensor for positional triggering on tumble blenders", "Pushbutton, timer and optical-sensor trigger options", "Real-time Moving Block endpoint detection for blending, drying, granulation and coating", "Washable IP65 / IP67 enclosure"]', '/products/viavi/micronir-pat-w.jpg')
) as v(sku, name, slug, description, specs, features, image_url)
cross join (select id from categories where slug = 'spectrophotometer') c
cross join (select id from brands where slug = 'viavi-solutions') b
on conflict (sku) do update set name = excluded.name, slug = excluded.slug, description = excluded.description, specs = excluded.specs,
  features = excluded.features, category_id = excluded.category_id, brand_id = excluded.brand_id, image_url = excluded.image_url, is_active = true;

select name, sku from products where sku like 'VIAVI-MICRONIR-%' order by sku;
